CREATE POLICY "studio_refs_select_own" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'studio-references' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "studio_refs_insert_own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'studio-references' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "studio_refs_update_own" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'studio-references' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "studio_refs_delete_own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'studio-references' AND auth.uid()::text = (storage.foldername(name))[1]);